args.command:
cd /app && blender_run --background /app/result.blend --python-expr "
import bpy
for o in bpy.context.scene.objects:
    if o.type=='MESH' and max(o.dimensions)>2.5 and 'wall' not in o.name and 'floor' not in o.name and 'ceil' not in o.name and 'rail' not in o.name and 'headboard' not in o.name:
        print('BIG:', o.name, tuple(round(v,2) for v in o.dimensions), tuple(round(v,2) for v in o.location))
" 2>/dev/null | grep BIG

